package ir.torsepan.mobile;
import org.json.*;import java.io.IOException;import java.nio.charset.StandardCharsets;import android.content.Context;
public class TransportChecks{
 static int checks;static void check(boolean b,String name){if(!b)throw new AssertionError(name);checks++;System.out.println("PASS "+name);}
 static String token(String owner){return "e30."+java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(("{\"sub\":\""+owner+"\",\"role\":\"Administrator\"}").getBytes(StandardCharsets.UTF_8))+".x";}
 static OfflineStore store(){OfflineStore s=new OfflineStore();s.put("owner","owner");s.put("token",token("owner"));s.put("refresh_token","refresh-old");s.put("enrolled","yes");s.put("snapshot","{}");s.rows.put(new JSONObject().put("id","operation-1").put("state","pending").put("body",new JSONObject().put("operationId","operation-1").put("action","tune")));return s;}
 static OfflineSync.Reply reply(int code,JSONObject body){return new OfflineSync.Reply(code,body);}static JSONObject ack(OfflineStore s){return new JSONObject().put("operationId","operation-1").put("deviceId",s.device()).put("registrarId","owner");}static JSONObject snapshot(){return new JSONObject().put("capturedUtc","2026-10-18T12:00:00Z").put("workspace",new JSONObject().put("sections",new JSONObject().put("photos",new JSONArray())));}
 public static void main(String[] args)throws Exception{
  OfflineStore s=store();int[] calls={0,0};OfflineSync sync=new OfflineSync(new Context(),s,(path,body)->{if(path.equals("operations")){calls[0]++;check(body.getString("operationId").equals("operation-1"),"refresh retry retains operation id");return reply(calls[0]==1?401:200,calls[0]==1?new JSONObject():ack(s));}if(path.equals("session")){calls[1]++;return reply(200,new JSONObject().put("accessToken",token("owner")).put("refreshToken","refresh-new"));}return reply(200,snapshot());});sync.sync();check(s.pending()==0&&calls[0]==2&&calls[1]==1,"expired access renews once then acknowledges same operation");check(s.get("refresh_token").equals("refresh-new"),"rotated refresh token is retained");
  OfflineStore lost=store();int[] retries={0};OfflineSync retry=new OfflineSync(new Context(),lost,(path,body)->{if(path.equals("operations")){if(retries[0]++==0)throw new IOException("lost");return reply(200,ack(lost));}return reply(200,snapshot());});retry.sync();check(lost.pending()==1,"lost response preserves pending operation");retry.sync();check(lost.pending()==0&&retries[0]==2,"same operation retries after lost response");
  OfflineStore bad=store();new OfflineSync(new Context(),bad,(path,body)->reply(200,new JSONObject())).sync();check(bad.pending()==1,"unexpected acknowledgement never discards operation");
  OfflineStore denied=store();new OfflineSync(new Context(),denied,(path,body)->reply(403,new JSONObject().put("message","denied"))).sync();check(denied.pending()==1&&denied.rows.getJSONObject(0).getString("state").equals("blocked"),"permission denial preserves blocked operation");
  OfflineStore wrong=store();new OfflineSync(new Context(),wrong,(path,body)->path.equals("session")?reply(200,new JSONObject().put("accessToken",token("another-owner")).put("refreshToken","wrong")):reply(401,new JSONObject())).sync();check(wrong.pending()==1&&wrong.get("refresh_token").equals("refresh-old"),"refresh for another account never replaces owner session");
  OfflineStore race=store();new OfflineSync(new Context(),race,(path,body)->{if(path.equals("session")){race.put("refresh_token","rotated-elsewhere");return reply(401,new JSONObject());}return reply(path.equals("operations")&&race.get("refresh_token").equals("refresh-old")?401:200,path.equals("operations")?ack(race):snapshot());}).sync();check(race.pending()==0&&race.get("refresh_token").equals("rotated-elsewhere"),"refresh race preserves newer credentials");
  OfflineStore cached=store();OfflineSync offline=new OfflineSync(new Context(),cached,(path,body)->{throw new IOException("offline");});check(offline.canOpen(),"cached prepared workshop opens when network is unavailable");
  OfflineStore photos=store();photos.rows=new JSONArray();String photo="22222222-2222-4222-8222-222222222222";JSONObject snap=snapshot();snap.getJSONObject("workspace").getJSONObject("sections").getJSONArray("photos").put(new JSONObject().put("id",photo).put("handpanId","33333333-3333-4333-8333-333333333333"));int[] downloads={0};OfflineSync images=new OfflineSync(new Context(),photos,(path,body)->{if(path.startsWith("asset/")){downloads[0]++;return reply(200,new JSONObject().put("contentType","image/jpeg").put("data","/9j/2Q=="));}return reply(200,snap);});images.sync();images.sync();check(downloads[0]==2,"full and thumbnail are cached once and reused");check(photos.has("photo:"+photo+":full")&&photos.has("photo:"+photo+":thumbnail"),"photo variants survive in native store");
  System.out.println("PASS "+checks+" native transport checks (Android SQLite and WebView need separate handset acceptance)");
 }
}
